<script module lang="ts">
/**
 * Value selection from a numeric range (`design/components/slider.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/slider.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/slider'
import { useMachine } from '@zag-js/svelte'

import {
  agentMember,
  attributes,
  joinSlot,
  mergeParts,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/slider.module.css'

export interface SliderProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: number | [number, number]
  disabled?: boolean
  /**
   * Formats both the readout and `aria-valuetext`.
   */
  formatValue?: (value: number) => string
  invalid?: boolean
  max?: number
  min?: number
  onChange?: ((value: number) => void) | ((value: [number, number]) => void)
  /**
   * Fires on release. Use it for expensive side effects instead of debouncing `onChange`. Radix
   * commits on pointer release and on each keyboard step, so a blurred slider never holds an
   * uncommitted value.
   */
  onCommit?: ((value: number) => void) | ((value: [number, number]) => void)
  /**
   * Two thumbs on one track. The pair is `[low, high]` and the thumbs cannot cross.
   */
  range?: boolean
  /**
   * Shows the current value at the row's end. Decorative, because the thumb announces it.
   */
  showValue?: boolean
  step?: number
  value?: number | [number, number]
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  formatValue = String,
  invalid: invalidOwn = false,
  max = 100,
  min = 0,
  onChange,
  onCommit,
  range = false,
  showValue = false,
  step = 1,
  value,
}: SliderProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let root = $state<HTMLElement | null>(null)
const documentDirection = useDirection(() => root)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      value: value === undefined ? undefined : Array.isArray(value) ? [...value] : [value],
      defaultValue:
        (defaultValue === undefined
          ? undefined
          : Array.isArray(defaultValue)
            ? [...defaultValue]
            : [defaultValue]) ?? (range ? [min, min] : [min]),
      min: min,
      max: max,
      step: step,
      disabled: disabled,
      invalid: invalid,
      getAriaValueText: (details) => formatValue(details.value),
      onValueChange: (details) => {
        ;(onChange as ((...args: any[]) => unknown) | undefined)?.(
          range ? [details.value[0] ?? min, details.value[1] ?? min] : (details.value[0] ?? min),
        )
      },
      onValueChangeEnd: (details) => {
        ;(onCommit as ((...args: any[]) => unknown) | undefined)?.(
          range ? [details.value[0] ?? min, details.value[1] ?? min] : (details.value[0] ?? min),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const spoken = $derived(api.value.map((value) => formatValue(value)))
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Slider',
    element: () => root?.querySelector('[role="slider"]'),
    state: () => ({
      value: api.value[0] ?? min,
      high: range ? (api.value[1] ?? min) : null,
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      set: { argument: 'number', run: (value) => api.setThumbValue(0, value) },
      'set-high': {
        argument: 'number',
        run: (value) =>
          (() => {
            if (!range) throw new Error('A single slider has one value, which set moves.')
            api.setThumbValue(1, value)
          })(),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-orientation="horizontal"
    data-member="slider"
    >{#if showValue}<span class={styles.readout} aria-hidden="true">{spoken.join('–')}</span>{/if
    }<div
      {...attributes(mergeParts(api.getRootProps(), api.getControlProps()))}
      class={styles.control}
      ><div {...attributes(api.getTrackProps())} class={styles.track}
        ><div {...attributes(api.getRangeProps())} class={styles.range}></div
      ></div
      >{#each api.value as _thumb, index (index)
        }<div
          {...attributes(api.getThumbProps({ index }))}
          class={styles.thumb}
          aria-label={ariaLabel}
          aria-labelledby={ariaLabelledby}
          aria-describedby={ariaDescribedby}
          aria-required={ariaRequired}
          aria-invalid={(invalid) ? true : undefined}
          data-state={Object(api.getThumbProps({ index }))['data-dragging'] === '' ? 'dragging' : undefined}
        ></div
      >{/each
    }</div
  ></div
>{/if
}{@render joined.end?.()}
